import{_ as a,o as r,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Calendar Card Pro","description":"Documentation non officielle en français pour Calendar Card Pro (Home Assistant).","frontmatter":{"title":"Calendar Card Pro","description":"Documentation non officielle en français pour Calendar Card Pro (Home Assistant)."},"headers":[],"relativePath":"fr/collection/calendar-card-pro/index.md","filePath":"fr/collection/calendar-card-pro/index.md","lastUpdated":1793128957000}'),o={name:"fr/collection/calendar-card-pro/index.md"};function i(l,e,d,c,s,u){return r(),t("div",null,[...e[0]||(e[0]=[n('<p><a id="orientation-actuelle"></a></p><h1 id="calendar-card-pro" tabindex="-1">Calendar Card Pro <a class="header-anchor" href="#calendar-card-pro" aria-label="Permalink to &quot;Calendar Card Pro {#calendar-card-pro}&quot;">​</a></h1><p>Calendar Card Pro est une carte de calendrier moderne et hautement personnalisable pour Home Assistant. Elle affiche les événements à venir de manière performante et claire. Elle prend en charge plusieurs calendriers, des vues compactes, une disposition en colonnes, la météo, des modèles (templates), des actions, des badges pour les événements sur toute la journée, des filtres par calendrier, ainsi qu&#39;un éditeur visuel.</p><div class="warning custom-block"><p class="custom-block-title">Documentation non officielle en français</p><p>Cette documentation est une traduction de travail non officielle en français, conçue pour une utilisation pratique. Le projet original Calendar Card Pro et sa documentation en anglais restent les références faisant foi.</p></div><img src="https://raw.githubusercontent.com/alexpfau/calendar-card-pro/main/.github/img/header.png" alt="Calendar Card Pro Vorschau" width="100%"><table tabindex="0"><thead><tr><th>Champ</th><th>Valeur</th></tr></thead><tbody><tr><td>Projet original</td><td><a href="https://github.com/alexpfau/calendar-card-pro" target="_blank" rel="noreferrer">alexpfau/calendar-card-pro</a></td></tr><tr><td>Documentation originale</td><td><a href="https://calendar-card-pro.alexpfau.com" target="_blank" rel="noreferrer">calendar-card-pro.alexpfau.com</a></td></tr><tr><td>Commit vérifié</td><td><a href="https://github.com/alexpfau/calendar-card-pro/commit/a3b01138daa44947f6673c33fe700e5ef4a08957" target="_blank" rel="noreferrer"><code>a3b01138daa44947f6673c33fe700e5ef4a08957</code></a></td></tr><tr><td>Version (Release)</td><td><a href="https://github.com/alexpfau/calendar-card-pro/releases/tag/v4.1.0" target="_blank" rel="noreferrer"><code>v4.1.0</code></a></td></tr><tr><td>Licence</td><td><a href="https://github.com/alexpfau/calendar-card-pro/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a></td></tr><tr><td>État</td><td>Documentation en français incluant l&#39;installation, l&#39;utilisation, les fonctionnalités, la référence, des exemples et le suivi des modifications</td></tr></tbody></table><h2 id="inhalt" tabindex="-1">Sommaire <a class="header-anchor" href="#inhalt" aria-label="Permalink to &quot;Sommaire {#inhalt}&quot;">​</a></h2><ul><li><a href="/fr/collection/calendar-card-pro/installation">Installation</a></li><li><a href="/fr/collection/calendar-card-pro/nutzung">Utilisation</a></li><li><a href="/fr/collection/calendar-card-pro/features">Fonctionnalités</a></li><li><a href="/fr/collection/calendar-card-pro/konfiguration">Référence de configuration</a></li><li><a href="/fr/collection/calendar-card-pro/beispiele">Exemples</a></li><li><a href="/fr/collection/calendar-card-pro/entwicklung">Développement et contribution</a></li><li><a href="/fr/collection/calendar-card-pro/lizenz-und-stand">Licence et état des sources</a></li></ul><h2 id="wofur-ist-die-karte-gedacht" tabindex="-1">À quoi sert cette carte ? <a class="header-anchor" href="#wofur-ist-die-karte-gedacht" aria-label="Permalink to &quot;À quoi sert cette carte ? {#wofur-ist-die-karte-gedacht}&quot;">​</a></h2><p>Calendar Card Pro est conçue pour les tableaux de bord (dashboards) où les événements de calendrier doivent être affichés de manière lisible, compacte et esthétique. Cette carte est particulièrement intéressante lorsque plusieurs calendriers sont regroupés, que l&#39;on souhaite distinguer les événements par couleur selon leur calendrier d&#39;origine, ou qu&#39;une vue hebdomadaire sous forme de colonnes est requise.</p><p>La carte nécessite au moins une entité Home Assistant de type <code>calendar.*</code>. Selon la documentation originale, elle a été testée notamment avec CalDAV et Google Calendar ; de manière générale, elle fonctionne avec toute intégration fournissant des entités de calendrier.</p>',11)])])}const m=a(o,[["render",i]]);export{f as __pageData,m as default};
